+
+    .intro {
+      margin: 0 0 1.5rem;
+      color: var(--muted);
+      max-width: 38rem;
+    }
+
+    form {
+      display: grid;
+      gap: 1.25rem;
+    }
+
+    .form-field {
+      padding: 1.25rem;
+      border: 1px solid rgba(124, 156, 255, 0.18);
+      border-radius: 1rem;
+      background: rgba(255, 255, 255, 0.02);
+    }
+
+    fieldset {
+      margin: 0;
+      padding: 0;
+      border: 0;
+    }
+
+    legend {
+      font-size: 1.05rem;
+      font-weight: 700;
+      margin-bottom: 0.5rem;
+      padding: 0;
+    }
+
+    .required {
+      color: var(--accent-strong);
+      margin-left: 0.25rem;
+    }
+
+    .help-text {
+      margin: 0 0 1rem;
+      color: var(--muted);
+      font-size: 0.95rem;
+    }
+
+    .options {
+      display: grid;
+      gap: 0.75rem;
+    }
+
+    .option {
+      display: flex;
+      align-items: center;
+      gap: 0.875rem;
+      padding: 0.9rem 1rem;
+      border: 1px solid rgba(180, 191, 220, 0.18);
+      border-radius: 0.875rem;
+      background: rgba(8, 12, 24, 0.45);
+      transition: border-color 160ms ease, background-color 160ms ease, transform 160ms ease;
+    }
+
+    .option:hover {
+      border-color: rgba(124, 156, 255, 0.55);
+      background: rgba(124, 156, 255, 0.07);
+    }
+
+    .option:has(input:focus-visible) {
+      border-color: var(--focus);
+      box-shadow: 0 0 0 3px rgba(245, 194, 107, 0.22);
+    }
+
+    input[type="radio"] {
+      width: 1.1rem;
+      height: 1.1rem;
+      margin: 0;
+      accent-color: var(--accent);
+      flex: 0 0 auto;
+    }
+
+    label {
+      cursor: pointer;
+      flex: 1;
+    }
+
+    .actions {
+      display: flex;
+      justify-content: flex-start;
+    }
+
+    button {
+      appearance: none;
+      border: 1px solid transparent;
+      border-radius: 0.9rem;
+      background: linear-gradient(180deg, var(--accent), #5f7fe8);
+      color: #09101f;
+      font: inherit;
+      font-weight: 700;
+      padding: 0.9rem 1.25rem;
+      min-width: 10rem;
+      cursor: pointer;
+      box-shadow: 0 10px 28px rgba(124, 156, 255, 0.26);
+      transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease;
+    }
+
+    button:hover {
+      filter: brightness(1.05);
+      transform: translateY(-1px);
+    }
+
+    button:focus-visible {
+      outline: 3px solid var(--focus);
+      outline-offset: 3px;
+    }
+
+    .status {
+      min-height: 1.5rem;
+      color: var(--success);
+      font-weight: 600;
+    }
+
+    .visually-hidden {
+      position: absolute;
+      width: 1px;
+      height: 1px;
+      padding: 0;
+      margin: -1px;
+      overflow: hidden;
+      clip: rect(0, 0, 0, 0);
+      white-space: nowrap;
+      border: 0;
+    }
+
+    @media (max-width: 480px) {
+      main {
+        padding: 1rem;
+      }
+
+      .card {
+        border-radius: 1rem;
+      }
+
+      button {
+        width: 100%;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main>
+    <section class="card" aria-labelledby="page-title">
+      <h1 id="page-title">Notification preferences</h1>
+      <p class="intro">Choose the single channel you want us to use for updates and alerts.</p>
+
+      <form id="notification-form" novalidate>
+        <div class="form-field">
+          <fieldset aria-describedby="notification-help">
+            <legend>
+              How do you prefer to receive notifications?
+              <span class="required" aria-hidden="true">*</span>
+            </legend>
+            <p class="help-text" id="notification-help">Select one option. This choice is required.</p>
+
+            <div class="options">
+              <div class="option">
+                <input id="notify-email" type="radio" name="notification-method" value="Email" required>
+                <label for="notify-email">Email</label>
+              </div>
+
+              <div class="option">
+                <input id="notify-sms" type="radio" name="notification-method" value="SMS" required>
+                <label for="notify-sms">SMS</label>
+              </div>
+
+              <div class="option">
+                <input id="notify-push" type="radio" name="notification-method" value="Push Notifications" required>
+                <label for="notify-push">Push Notifications</label>
+              </div>
+            </div>
+          </fieldset>
+        </div>
+
+        <div class="actions">
+          <button type="submit">Save preference</button>
+        </div>
+
+        <p id="status" class="status" aria-live="polite"></p>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.getElementById('notification-form');
+    const radios = Array.from(form.querySelectorAll('input[type="radio"]'));
+    const status = document.getElementById('status');
+
+    form.addEventListener('submit', (event) => {
+      event.preventDefault();
+
+      const selected = radios.find((radio) => radio.checked);
+
+      if (!selected) {
+        status.textContent = 'Please choose one notification method before saving.';
+        radios[0].focus();
+        return;
+      }
+
+      status.textContent = `Preference saved: ${selected.value}.`;
+    });
+  </script>
+</body>
+</html>
*** End Patch
