  <title>Notification Preferences</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #121a2f;
      --panel-border: #27324d;
      --text: #eef2ff;
      --muted: #b4bfdc;
      --accent: #7c9cff;
      --accent-strong: #9fb3ff;
      --focus: #f5c26b;
      --success: #73e2a7;
      --shadow: 0 22px 60px rgba(0, 0, 0, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    html, body {
      min-height: 100%;
    }

    body {
      margin: 0;
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(124, 156, 255, 0.16), transparent 35%),
        linear-gradient(180deg, #0b1020 0%, #0d1326 100%);
      color: var(--text);
      line-height: 1.5;
    }

