  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content">
    <section class="card" aria-labelledby="page-title">
      <h1 id="page-title">Notification preferences</h1>
      <p class="intro">Choose the single channel you want us to use for updates and alerts.</p>

      <form id="notification-form">
        <div class="form-field">
          <fieldset aria-describedby="notification-help">
            <legend>
              How do you prefer to receive notifications?
              <span class="required" aria-hidden="true">*</span>
            </legend>
            <p class="help-text" id="notification-help">Select one option. This choice is required.</p>

            <div class="options">
              <div class="option">
                <input id="notify-email" type="radio" name="notification-method" value="Email" required>
                <label for="notify-email">Email</label>
              </div>

              <div class="option">
                <input id="notify-sms" type="radio" name="notification-method" value="SMS" required>
                <label for="notify-sms">SMS</label>
              </div>

              <div class="option">
                <input id="notify-push" type="radio" name="notification-method" value="Push Notifications" required>
                <label for="notify-push">Push Notifications</label>
              </div>
            </div>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Save preference</button>
        </div>

        <p id="status" class="status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('notification-form');
    const radios = Array.from(form.querySelectorAll('input[type="radio"]'));
    const status = document.getElementById('status');

    radios.forEach((radio) => {
      radio.addEventListener('change', () => {
        status.textContent = '';
      });
    });

    form.addEventListener('submit', (event) => {
      if (!form.checkValidity()) {
        status.textContent = 'Please choose one notification method before saving.';
        return;
      }

      const selected = radios.find((radio) => radio.checked);

      event.preventDefault();

      status.textContent = `Preference saved: ${selected.value}.`;
    });
  </script>
</body>
</html>
