   <a class="skip-link" href="#main-content">Skip to main content</a>
   <main id="main-content">
     <section class="card" aria-labelledby="page-title">
       <h1 id="page-title">Notification preferences</h1>
       <p class="intro">Choose the single channel you want us to use for updates and alerts.</p>

       <form id="notification-form">
         <div class="form-field">
           <fieldset aria-describedby="notification-help">
             <legend>
               How do you prefer to receive notifications?
               <span class="required" aria-hidden="true">*</span>
             </legend>
             <p class="help-text" id="notification-help">Select one option. This choice is required.</p>

